import re

class Router:
    def __init__(self):
        self.routes = [] # list of (pattern_tuple, name, regex, params)

    def add(self, pattern: str, name: str) -> None:
        if not pattern.startswith('/'):
            raise ValueError("Pattern must start with /")

        parts = [p for p in pattern.split('/') if p]
        # The split logic above is slightly wrong because we need to preserve empty segments 
        # except the first one? No, "segments split on /". "/a/b" -> ["", "a", "b"]
        # Let's re-evaluate: "A pattern begins with / and is read as segments split on /."
        # If path is "/a/b", parts are ["", "a", "b"]. 
        # But the rules say "segments". Usually, leading slash doesn't count as a segment.
        # Let's check: "{name}" matches exactly one segment.
        # If pattern is "/{id}", segments are ["", "{id}"].
        # Actually, let's split by "/" and ignore the first empty string if it exists.
        raw_segments = pattern.split('/')
        if raw_segments[0] == '':
            segments = raw_segments[1:]
        else:
            segments = raw_segments

        parsed_segments = []
        for i, seg in enumerate(segments):
            if not seg: continue # Should not happen based on rules? "never matches an empty segment"
            if seg.startswith('{') and seg.endswith('}'):
                inner = seg[1:-1]
                if inner == '*':
                    raise ValueError("Empty parameter name")
                if inner.endswith(':*'):
                    if i != len(segments) - 1:
                        raise ValueError("{name:*} must be last")
                    parsed_segments.append(('wild', inner[:-2]))
                elif inner == '': # Should not happen if we check for {:}
                     raise ValueError("Empty parameter name")
                else:
                    if '{' in inner or '}' in inner: raise ValueError("Unmatched brace")
                    parsed_segments.append(('param', inner))
            else:
                parsed_segments.append(('literal', seg))

        # Check for duplicates (different names, same structure)
        for p_seg, r_name in self.routes:
            if p_seg == parsed_segments:
                raise ValueError(f"Pattern {pattern} already registered")

        # Build regex
        regex_parts = []
        param_names = []
        for i, (type, val) in enumerate(parsed_segments):
            if type == 'literal':
                regex_parts.append(re.escape(val))
            elif type == 'param':
                param_names.append(val)
                regex_parts.append(f"([{ '^' }])") # Placeholder, will fix
                # Wait, regex for {name} is just the segment content? 
                # No, it matches exactly one segment. So it matches any non-slash chars.
                regex_parts[-1] = r"([^/]+)"
            elif type == 'wild':
                param_names.append(val)
                regex_parts.append(r".*")

        # Actually, let's just build the regex properly
        regex_str = "^" + "/".join(re.escape(v) if t == 'literal' else r"([^/]+)" if t == 'param' else r".*" for t, v in parsed_segments) + "$"
        # Wait, the join is wrong because of leading slash.
        # Let's do it manually.
        regex_parts = []
        for i, (t, v) in enumerate(parsed_segments):
            if t == 'literal':
                regex_parts.append(re.escape(v))
            elif t == 'param':
                regex_parts.append(r"([^/]+)")
            elif t == 'wild':
                regex_parts.append(r".*")

        # The path starts with / so we need to handle that.
        # If pattern is "/a", segments are ["a"]. Path is "/a".
        # So regex should be ^/a$ or similar.
        full_regex = "^/" + "/".join(regex_parts) + "$"
        self.routes.append((parsed_segments, name, re.compile(full_regex), param_names))

    def match(self, path: str) -> tuple[str, dict[str, str]] | None:
        best_match = None
        max_score = (-1, -1) # (specificity_tuple, num_segments)

        for p_seg, r_name, reg, param_names in self.routes:
            m = reg.match(path)
            if m:
                # Calculate specificity
                # Rank: literal=3, param=2, wild=1
                score = []
                for i, (t, v) in enumerate(p_seg):
                    if t == 'literal': score.append(3)
                    elif t == 'param': score.append(2)
                    else: score.append(1)

                current_score = (tuple(score), len(p_seg))

                if best_match is None or current_score > max_score:
                    max_score = current_score
                    best_match = (r_name, m.groups(), param_names)

        if best_match:
            name, groups, p_names = best_match
            return name, dict(zip(p_names, groups))
        return None
