        for p_segs, name in self.routes:
            current_params = {}
            match_found = True
            p_idx = 0
            path_idx = 0

            # This is tricky because {name} matches one, {name:*} matches rest.
            # We need to simulate the matching process.
            def backtrack(p_i, path_i, params):
                if p_i == len(p_segs):
                    return (True, params) if path_i == len(path_parts) else (False, None)

                if path_i >= len(path_parts): return False, None

                type, val = p_segs[p_i]
                if type == 'literal':
                    if path_parts[path_i] == val:
                        res, p = backtrack(p_i + 1, path_i + 1, params)
                        return res, p
                    return False, None
                elif type == 'param':
                    if path_parts[path_i] != '': # Contract says {name} never matches empty
                        res, p = backtrack(p_i + 1, path_i + 1, {**params, val: path_parts[path_i]})
                        return res, p
                    return False, None
                elif type == 'wild':
                    # Matches remainder
                    remainder = "/".join(path_parts[path_i:])
                    if remainder:
                        res, p = backtrack(p_i + 1, len(path_parts), {**params, val: remainder})
                        return res, p
                    return False, None

                return False, None

            # The logic above is slightly flawed for "matches the whole remainder".
            # Let's simplify. Since there's only one wildcard and it's last:
            res_params = {}
            possible = True
            curr_p = 0
            for i, seg in enumerate(p_segs):
                stype, sval = seg
                if stype == 'literal':
                    if curr_p < len(path_parts) and path_parts[curr_p] == sval:
                        curr_p += 1
                    else:
                        possible = False; break
                elif stype == 'param':
                    if curr_p < len(path_parts) and path_parts[curr_p] != '':
                        res_params[sval] = path_parts[curr_p]
                        curr_p += 1
                    else:
                        possible = False; break
                elif stype == 'wild':
                    remainder = "/".join(path_parts[curr_p:])
                    if remainder:
                        res_params[sval] = remainder
                        curr_p = len(path_parts)
                    else:
                        possible = False; break

            if possible and curr_p == len(path_parts):
                matches.append((p_segs, name, res_params))

        if not matches: return None

        # Specificity ranking: literal > param > wild
        # Compare segment by segment from left
        def get_winner(m1, m2):
            s1, n1, p1 = m1
            s2, n2, p2 = m2
            for i in range(max(len(s1), len(s2))):
                if i >= len(s1): return 1 # s2 is longer/more specific? No, "pattern with more segments wins" if same.
                if i >= len(s2): return -1

                t1 = s1[i][0]
                t2 = s2[i][0]
                if t1 != t2:
                    # Rank: literal (0), param (1), wild (2)
                    ranks = {'literal': 0, 'param': 1, 'wild': 2}
                    return 1 if ranks[t1] < ranks[t2] else -1

            return 1 if len(s1) > len(s2) else -1

        # Sort matches by specificity
        best = matches[0]
        for i in range(1, len(matches)):
            if get_winner(matches[i], best) > 0:
                best = matches[i]

        return (best[1], best[2])

