        # Wait, the contract says "read as segments split on /". 
        # Usually this means "/a//b" has an empty segment in the middle.
        # Let's check: "/a/b" -> ["", "a", "b"]? No, usually it's just splitting by /.
        # If pattern is "/a/b", split('/') gives ['', 'a', 'b']. 
        # The first empty string is because of the leading slash.
        segments = pattern.split('/')[1:]
        if pattern == '/': segments = []

        parsed_segments = []
        for i, seg in enumerate(segments):
            if not seg: raise ValueError("Empty segment")
            if seg.startswith('{') and seg.endswith('}'):
                inner = seg[1:-1]
                if inner.startswith('*'): # Should be {name:*}, but let's check logic
                    pass 
                elif inner.endswith('*'):
                    name_part = inner[:-1]
                    if not name_part: raise ValueError("Empty parameter name")
                    if i != len(segments) - 1: raise ValueError("{name:*} must be last")
                    parsed_segments.append(('wild', name_part))
                elif name_part := inner: # {name}
                    parsed_segments.append(('param', name_part))
                else:
                    raise ValueError("Empty parameter name")
            else:
                parsed_segments.append(('literal', seg))

        # Check for duplicate patterns (same structure, different names)
        for p_segs, p_name, _ in self.routes:
            if p_segs == parsed_segments:
                raise ValueError(f"Pattern {pattern} already registered")

        self.routes.append((parsed_segments, name))

