        self.routes = []

    def add(self, pattern: str, name: str) -> None:
        if not pattern.startswith('/'):
            raise ValueError("Pattern must start with /")

        segments_raw = pattern.split('/')
        # segments_raw[0] is always "" because of leading slash
        segments_raw = segments_raw[1:]
        if pattern == '/':
            segments_raw = []

        parsed_segments = []
        for i, seg in enumerate(segments_raw):
            if not seg:
                raise ValueError("Empty segment")
            if seg.startswith('{') and seg.endswith('}'):
                inner = seg[1:-1]
                if inner.endswith('*'):
                    name_part = inner[:-1]
                    if not name_part:
                        raise ValueError("Empty parameter name")
                    if i != len(segments_raw) - 1:
                        raise ValueError("{name:*} must be last")
                    parsed_segments.append(('wild', name_part))
                elif inner:
                    parsed_segments.append(('param', inner))
                else:
                    raise ValueError("Empty parameter name")
            else:
                parsed_segments.append(('literal', seg))

        for p_segs, _ in self.routes:
            if p_segs == parsed_segments:
                raise ValueError(f"Pattern {pattern} already registered")

        self.routes.append((parsed_segments, name))

    def match(self, path: str) -> tuple[str, dict[str, str]] | None:
        path_parts = path.split('/')[1:]
        matches = []
        for p_segs, name in self.routes:
            res_params = {}
            possible = True
            curr_p = 0
            for i, (stype, sval) in enumerate(p_segs):
                if stype == 'literal':
                    if curr_p < len(path_parts) and path_parts[curr_p] == sval:
                        curr_p += 1
                    else:
                        possible = False; break
                elif stype == 'param':
                    if curr_p < len(path_parts) and path_parts[curr_p] != '':
                        res_params[sval] = path_parts[curr_p]
                        curr_p += 1
                    else:
                        possible = False; break
                elif stype == 'wild':
                    remainder = "/".join(path_parts[curr_p:])
                    if remainder:
                        res_params[sval] = remainder
                        curr_p = len(path_parts)
                    else:
                        possible = False; break

            if possible and curr_p == len(path_parts):
                matches.append((p_segs, name, res_params))

        if not matches: return None

        def get_winner(m1, m2):
            s1, n1, p1 = m1
            s2, n2, p2 = m2
            for i in range(max(len(s1), len(s2))):
                if i >= len(s1): return -1 # s1 is shorter
                if i >= len(s2): return 1  # s2 is shorter (wait, if s1 is longer it wins)

                t1 = s1[i][0]
                t2 = s2[i][0]
                if t1 != t2:
                    ranks = {'literal': 0, 'param': 1, 'wild': 2}
                    return 1 if ranks[t1] < ranks[t2] else -1

            # If they are the same length and all types match
            if len(s1) > len(s2): return 1
            if len(s1) < len(s2): return -1
            return 0

        best = matches[0]
        for i in range(1, len(matches)):
            if get_winner(matches[i], best) > 0:
                best = matches[i]

        # Re-checking the "pattern with more segments wins" rule.
        # If they are identical up to the end of the shorter one, 
        # and s1 is longer, then s1 wins.
        # My get_winner logic:
        # if i >= len(s1): return -1 (means m2 is longer at this point)
        # wait, let's re-write it clearly.

        def compare(m1, m2):
            s1, n1, p1 = m1
            s2, n2, p2 = m2
            for i in range(min(len(s1), len(s2))):
                t1 = s1[i][0]
                t2 = s2[i][0]
                if t1 != t2:
                    ranks = {'literal': 0, 'param': 1, 'wild': 2}
                    return 1 if ranks[t1] < ranks[t2] else -1

            if len(s1) != len(s2):
                return 1 if len(s1) > len(s2) else -1
            return 0

        best = matches[0]
        for i in range(1, len(matches)):
            if compare(matches[i], best) > 0:
                best = matches[i]

        return (best[1], best[2])
