from typing import Callable, Any

def retry(fn: Callable[[], Any], *, attempts: int, backoff_s: float, max_backoff_s: float,
           retry_on: tuple[type[BaseException], ...], sleep: Callable[[float], None]) -> Any:
    if attempts < 1:
        raise ValueError("attempts must be at least 1")

    last_exception = None
    for k in range(1, attempts + 1):
        try:
            return fn()
        except BaseException as e:
            # Check if the exception is one of the retryable types (or a subclass)
            is_retryable = False
            for base_type in retry_on:
                if isinstance(e, base_type):
                    is_retryable = True
                    break

            if not is_retryable:
                raise e

            last_exception = e
            # If this was the last attempt, don't sleep and raise original exception
            if k == attempts:
                raise last_exception

            # Calculate delay for the current failure (k-th)
            delay = min(backoff_s * (2 ** (k - 1)), max_backoff_s)
            sleep(delay)

    # This part should technically not be reachable because of the k == attempts check,
    # but we raise last_exception just in case.
    if last_exception:
        raise last_exception
EOF

