            for retry_type in retry_on:
                if isinstance(e, retry_type):
                    is_retryable = True
                    break

            if not is_retryable:
                raise e

            last_exception = e

            # If this was the last attempt, don't sleep and raise the exception.
            if k == attempts:
                raise last_exception

            # Calculate delay for the next attempt.
            delay = min(backoff_s * (2 ** (k - 1)), max_backoff_s)
            sleep(delay)

    # This part should theoretically not be reached because we raise in the loop,
    # but it's good practice to have a fallback or just let the last exception bubble.
    if last_exception:
        raise last_exception
