def retry(fn: Callable[[], Any], *, attempts: int, backoff_s: float, max_backoff_s: float,
           retry_on: tuple[Type[BaseException], ...], sleep: Callable[[float], None]) -> Any:
    if attempts < 1:
        raise ValueError("attempts must be at least 1")

    last_exception = None
    for k in range(1, attempts + 1):
        try:
            return fn()
        except Exception as e:
            # Check if the exception is one of the types we should retry on.
            # We must check if it's an instance of any type in retry_on.
            is_retryable = False
            for retry_type in retry_on:
                if isinstance(e, retry_type):
                    is_retryable = True
                    break

            if not is_retryable:
                raise e

            last_exception = e

            # If this was the last attempt, don't sleep and raise the exception.
            if k == attempts:
                raise last_exception

            # Calculate delay for the next attempt.
            delay = min(backoff_s * (2 ** (k - 1)), max_backoff_s)
            sleep(delay)

    # This part should theoretically not be reached because we raise in the loop,
    # but it's good practice to have a fallback or just let the last exception bubble.
    if last_exception:
        raise last_exception
