import re

def render(template, data):
    def get_nested(path, context, in_loop=False):
        if not path:
            raise ValueError("Empty placeholder")

        # Rule: {{.}} or {{.field}} outside any block -> ValueError
        if path.startswith("."):
            if not in_loop:
                raise ValueError("Dot notation outside loop")

            if path == ".":
                return context

            parts = path[1:].split(".")
            curr = context
            for p in parts:
                if not p: continue
                if isinstance(curr, dict) and p in curr:
                    curr = curr[p]
                else:
                    raise KeyError(path)
            return curr
        else:
            # Rule: names that do not begin with . are still looked up in data.
            parts = path.split(".")
            curr = context
            for p in parts:
                if not p: continue
                if isinstance(curr, dict) and p in curr:
                    curr = curr[p]
                else:
                    raise KeyError(path)
            return curr

    def parse_recursive(text, context, in_loop=False):
        result = []
        i = 0
        while i < len(text):
            if text[i:i+2] == "\\{":
                # Check if it's \{{ or just \{
                # The rule says "\{{" renders as literal "{{" and starts no placeholder.
                # This implies we should look for the next { to see if it's a double {{.
                if i + 2 < len(text) and text[i+2] == "{":
                    result.append("{{")
                    i += 3 # Skip \{{
                else:
                    # This is just \{ followed by something else, or end of string.
                    # The rule doesn't specify what to do with \, so we assume it's literal.
                    result.append("\\")
                    i += 1
            elif text[i:i+2] == "{{":
                j = text.find("}}", i + 2)
                if j == -1:
                    raise ValueError("Malformed placeholder")
                content = text[i+2:j].strip()

                if not content:
                    raise ValueError("Empty placeholder")

                if content.startswith("!"):
                    # Comment
                    i = j + 2
                    continue
                elif content.startswith("#each"):
                    # Loop
                    if in_loop:
                        raise ValueError("Nested #each not allowed")

                    # Find matching /each
