import re

def render(template, data):
    # 1. Handle \{{ as literal {{ and remove it from consideration for tags
    # We can do this by replacing \{{ with a special placeholder that won't be matched.
    # But we need to be careful not to replace actual {{ if they are part of something else.
    # Actually, the rule is: \{{ renders as literal {{ and starts no placeholder.
    # This means we can just treat it as a special token.

    def get_tokens(text):
        tokens = []
        i = 0
        while i < len(text):
            if text[i:i+3] == "\\{{":
                tokens.append(('literal', '{{'))
                i += 3
            elif text[i:i+2] == "{{":
                end_idx = text.find("}}", i + 2)
                if end_idx == -1:
                    raise ValueError("Malformed template: unclosed placeholder")
                content = text[i+2 : end_idx].strip()
                tokens.append(('tag', content))
                i = end_idx + 2
            else:
                next_tag = -1
                for j in range(i, len(text)):
                    if text[j:j+2] == "{{":
                        next_tag = j
                        break
                    if text[j:j+3] == "\\{{":
                        next_tag = j
                        break
                if next_tag == -1:
                    tokens.append(('text', text[i:]))
                    break
                else:
                    tokens.append(('text', text[i:next_tag]))
                    i = next_tag
        return tokens

    # Wait, the above get_tokens is slightly wrong because it might skip \{{ 
    # when looking for {{. Let's refine it.
    def get_tokens_refined(text):
        tokens = []
        i = 0
        while i < len(text):
            if text[i:i+3] == "\\{{":
                tokens.append(('literal', '{{'))
                i += 3
            elif text[i:i+2] == "{{":
                # We found a {{, but we must make sure it's not part of \{{
                # Since we already checked for \{{ above, this is safe.
                end_idx = text.find("}}", i + 2)
                if end_idx == -1:
                    raise ValueError("Malformed template: unclosed placeholder")
                content = text[i+2 : end_idx].strip()
                tokens.append(('tag', content))
                i = end_idx + 2
            else:
                # Find next tag start
                next_tag = -1
                for j in range(i, len(text)):
                    if text[j:j+3] == "\\{{":
                        next_tag = j
                        break
                    if text[j:j+2] == "{{":
                        next_tag = j
                        break
                if next_tag == -1:
                    tokens.append(('text', text[i:]))
                    break
                else:
                    tokens.append(('text', text[i:next_tag]))
                    i = next_tag
        return tokens

    # Actually, the easiest way to handle \{{ and {{ is a single pass parser.
    # Let's use a more robust approach.

    def parse_template(tpl):
        tokens = []
        i = 0
        while i < len(tpl):
            if tpl[i:i+3] == "\\{{":
                tokens.append(('literal', '{{'))
                i += 3
            elif tpl[i:i+2] == "{{":
                end_idx = tpl.find("}}", i + 2)
                if end_idx == -1:
                    raise ValueError("Malformed template: unclosed placeholder")
                content = tpl[i+2 : end_idx].strip()
                tokens.append(('tag', content))
                i = end_idx + 2
            else:
                j = i
                while j < len(tpl) and tpl[j:j+2] != "{{" and tpl[j:j+3] != "\\{{":
                    j += 1
                tokens.append(('text', tpl[i:j]))
                i = j
        return tokens

    tokens = parse_template(template)

    # Now we need to handle the tags. Some are comments, some are #each, some are /each, some are placeholders.
    # Because nested each is forbidden, we can process this linearly.

    def resolve_path(path, context):
        parts = path.split('.')
        current = context
        for part in parts:
            if part == '.':
