    while i < len(template):
        if template[i:i+3] == r'\{{':
            parts.append(('literal', '{{'))
            i += 3
        elif template[i:i+2] == '{{':
            end_idx = template.find('}}', i + 2)
            if end_idx == -1:
                raise ValueError("a {{ with no }} after it")
            content = template[i+2 : end_idx].strip()
            parts.append(('tag', content, i + 2, end_idx))
            i = end_idx + 2
        else:
            # Find the next occurrence of {{ or \{{
            next_special = len(template)
            for j in range(i, len(template)):
                if template[j:j+2] == '{{':
                    next_special = min(next_special, j)
                elif template[j:j+3] == r'\{{':
                    next_special = min(next_special, j)
                if next_special != len(template):
                    break
            parts.append(('text', template[i:next_special]))
            i = next_special

